def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        chain_dict[a] = b

    chain_dict[chain[0]] = chain[1]

    stack = [chain[0]]
    result = []

    while stack:
        current = stack.pop()
        result.append(current)

        next_node = chain_dict.get(current)
        if next_node is not None:
            stack.append(next_node)

    return ','.join(result)
```

